/* Interactive normalized scaling chart for the survey project page.
 * Reads window.SCALING_DATA (generated by scripts/build_dataset.py) and renders
 * an Apache ECharts scatter plot with filters, hover details, a click-to-detail
 * panel, a reference list, and a table view. Plain ES2017, no build step. */
(function () {
  "use strict";
  const D = window.SCALING_DATA;
  if (!D || !window.echarts) {
    document.getElementById("chart").textContent = "Chart data or ECharts failed to load.";
    return;
  }

  // ------------------------------------------------------------------ helpers
  const $ = (sel, root) => (root || document).querySelector(sel);
  const esc = (s) => String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const METRIC = {};
  D.metrics.forEach((m) => { METRIC[m.key] = m; });
  const SYMBOLS = { plus: "path://M4,0 H6 V4 H10 V6 H6 V10 H4 V6 H0 V4 H4 Z" };
  const DATASET_LABEL = { "survey-figure": "Survey Figure 2", "survey-table": "Survey tables (Sec. 5)", "chip-corpus": "Chip corpus (public/chips)" };
  const STATUS_LABEL = { released: "Released", preliminary: "Preliminary", forthcoming: "Forthcoming" };

  function fmtDate(iso, precision) {
    const [y, m] = iso.split("-");
    if (precision === "year") return y;
    return MONTHS[parseInt(m, 10) - 1] + " " + y;
  }
  function fmtNum(v) {
    if (v >= 1000) return v.toLocaleString("en-US", { maximumFractionDigits: 0 });
    if (v >= 100) return v.toLocaleString("en-US", { maximumFractionDigits: 1 });
    if (v >= 1) return v.toLocaleString("en-US", { maximumFractionDigits: 2 });
    return v.toLocaleString("en-US", { maximumSignificantDigits: 3 });
  }
  function fmtNorm(v) {
    if (v >= 100) return "×" + v.toLocaleString("en-US", { maximumFractionDigits: 0 });
    if (v >= 10) return "×" + v.toFixed(1);
    return "×" + v.toFixed(2);
  }
  function refTag(refs) { return refs.map((n) => "[" + n + "]").join(""); }

  // Endpoint annualised growth, identical to scripts/build_dataset.py::growth_rate.
  function growthRate(points) {
    if (!points.length) return null;
    const ordered = points.slice().sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : a.name.localeCompare(b.name)));
    const start = ordered[0];
    let max = -Infinity, end = start;
    ordered.forEach((p) => { if (p.value > max) { max = p.value; end = p; } });
    const days = (Date.parse(end.date) - Date.parse(start.date)) / 86400000;
    const years = days / 365.2425;
    if (years <= 0) return { pct: 0, start, end };
    return { pct: (Math.pow(end.value / start.value, 1 / years) - 1) * 100, start, end };
  }

  // ------------------------------------------------------------------ state
  const ALL = {
    metrics: D.metrics.map((m) => m.key),
    vendors: D.vendors.slice(),
    statuses: D.statuses.slice(),
    datasets: D.datasets.slice(),
  };
  const state = {
    metrics: new Set(ALL.metrics),
    vendors: new Set(ALL.vendors),
    statuses: new Set(ALL.statuses),
    datasets: new Set(ALL.datasets),
    labels: "auto",          // "auto" | true | false
    selected: null,          // product id shown in the detail panel
  };
  const LABEL_AUTO_LIMIT = 60;

  function visiblePoints() {
    return D.points.filter((p) =>
      state.metrics.has(p.metric) &&
      state.statuses.has(p.status) &&
      state.datasets.has(p.dataset) &&
      (p.kind === "model" || state.vendors.has(p.vendor)));
  }

  // ------------------------------------------------------------------ filters
  const GROUPS = {
    metrics: { title: "Metric", options: D.metrics.map((m) => ({ id: m.key, label: m.label, color: m.color })) },
    vendors: { title: "Vendor", options: D.vendors.map((v) => ({ id: v, label: v })) },
    statuses: { title: "Status", options: D.statuses.map((s) => ({ id: s, label: STATUS_LABEL[s] || s })) },
    datasets: { title: "Data set", options: D.datasets.map((d) => ({ id: d, label: DATASET_LABEL[d] || d })) },
  };

  function buildMenus() {
    document.querySelectorAll("#filters details").forEach((det) => {
      const g = det.dataset.group;
      const menu = $(".menu", det);
      const opts = GROUPS[g].options;
      menu.innerHTML =
        '<label class="all"><input type="checkbox" data-all="1"> Select all</label>' +
        opts.map((o) =>
          '<label><input type="checkbox" value="' + esc(o.id) + '">' +
          (o.color ? '<span class="swatch" style="background:' + o.color + '"></span>' : "") +
          esc(o.label) + "</label>").join("");
      menu.addEventListener("change", (ev) => {
        const input = ev.target;
        if (input.dataset.all) {
          if (input.checked) state[g] = new Set(ALL[g]); else state[g].clear();
        } else if (input.checked) state[g].add(input.value); else state[g].delete(input.value);
        syncMenus();
        render();
      });
      // close other menus when one opens
      det.addEventListener("toggle", () => {
        if (det.open) document.querySelectorAll("#filters details[open]").forEach((o) => { if (o !== det) o.open = false; });
      });
    });
    document.addEventListener("click", (ev) => {
      if (!ev.target.closest("#filters details")) document.querySelectorAll("#filters details[open]").forEach((o) => { o.open = false; });
    });
  }

  function syncMenus() {
    document.querySelectorAll("#filters details").forEach((det) => {
      const g = det.dataset.group;
      det.querySelectorAll('input[type="checkbox"]').forEach((input) => {
        if (input.dataset.all) {
          input.checked = state[g].size === ALL[g].length;
          input.indeterminate = state[g].size > 0 && state[g].size < ALL[g].length;
        } else input.checked = state[g].has(input.value);
      });
      $(".count", det).textContent = state[g].size + "/" + ALL[g].length;
    });
    const t = $("#labels-toggle");
    t.checked = state.labels === true || (state.labels === "auto" && visiblePoints().length <= LABEL_AUTO_LIMIT);
  }

  // ------------------------------------------------------------------ chart
  const chart = echarts.init($("#chart"), null, { renderer: "canvas" });
  let growth = {};

  function seriesFor(metric, pts, showLabels) {
    const m = METRIC[metric];
    return {
      name: m.label,
      type: "scatter",
      symbol: SYMBOLS[m.symbol] || m.symbol,
      symbolSize: 11,
      itemStyle: { color: m.color, borderColor: m.color, borderWidth: 1.5 },
      emphasis: { focus: "none", scale: 1.4 },
      label: {
        show: showLabels, position: "right", distance: 5, fontSize: 10.5, color: "#4a4a52",
        formatter: (p) => p.data.pt.label,
      },
      labelLayout: { hideOverlap: true, moveOverlap: "shiftY" },
      data: pts.map((p) => ({
        value: [p.date, p.normalized],
        pt: p,
        itemStyle: p.status === "released" ? undefined : { color: "#ffffff", borderColor: m.color, borderWidth: 2 },
      })),
      z: 3,
    };
  }

  function tooltipHtml(params) {
    const p = params.data.pt;
    const m = METRIC[p.metric];
    return '<div class="tip"><b>' + esc(p.label) + "</b>" + (p.label !== p.name ? " · " + esc(p.name) : "") + "<br>" +
      '<span class="k">' + esc(p.vendor) + " · " + fmtDate(p.date, p.date_precision) + "</span><br>" +
      esc(m.label) + ": <b>" + fmtNum(p.value) + " " + esc(p.unit) + "</b> (" + fmtNorm(p.normalized) + ")<br>" +
      '<span class="k">Status:</span> <span class="status">' + esc(p.status) + "</span> · " +
      '<span class="k">Source:</span> <span class="ref">' + refTag(p.refs) + "</span>" +
      (p.note ? '<br><span class="k">' + esc(p.note) + "</span>" : "") +
      '<br><span class="k">Click for details</span></div>';
  }

  function baseOption() {
    return {
      animation: false,
      grid: { left: 64, right: 24, top: 72, bottom: 70, containLabel: false },
      legend: {
        top: 6, left: 8, width: "82%", orient: "horizontal", itemGap: 14, itemWidth: 14, itemHeight: 12,
        textStyle: { fontSize: 12.5, color: "#1b1b1f" },
        data: D.metrics.map((m) => m.label),
        selected: Object.fromEntries(D.metrics.map((m) => [m.label, state.metrics.has(m.key)])),
        formatter: (name) => {
          const g = growth[name];
          return g ? name + ": " + (g.pct >= 0 ? "+" : "") + g.pct.toFixed(0) + "%/yr" : name;
        },
      },
      tooltip: { trigger: "item", confine: true, borderColor: "#cfcfca", backgroundColor: "#fff", textStyle: { color: "#1b1b1f" }, formatter: tooltipHtml },
      toolbox: { right: 12, top: 6, feature: { restore: { title: "Reset zoom" }, saveAsImage: { title: "Save image", name: "scaling-chart", pixelRatio: 2 } } },
      xAxis: {
        type: "time", min: "2016-01-01", max: "2027-01-01", name: "Release date", nameLocation: "middle", nameGap: 30,
        axisLabel: { formatter: "{yyyy}" }, splitLine: { show: true, lineStyle: { type: "dashed", color: "#e3e3e0" } },
        axisLine: { lineStyle: { color: "#cfcfca" } },
      },
      yAxis: {
        type: "log", logBase: 10, name: "Normalized scaling (log scale)", nameLocation: "middle", nameGap: 44,
        splitLine: { lineStyle: { type: "dashed", color: "#e3e3e0" } }, axisLine: { lineStyle: { color: "#cfcfca" } },
        axisLabel: { formatter: (v) => (v >= 1 ? "×" + fmtNum(v) : "×" + v) },
      },
      dataZoom: [
        { type: "inside", xAxisIndex: 0, filterMode: "none" },
        { type: "inside", yAxisIndex: 0, filterMode: "none" },
        { type: "slider", xAxisIndex: 0, bottom: 10, height: 18, filterMode: "none", labelFormatter: (v) => new Date(v).getUTCFullYear() },
      ],
      series: [],
    };
  }

  function render() {
    const pts = visiblePoints();
    const showLabels = state.labels === true || (state.labels === "auto" && pts.length <= LABEL_AUTO_LIMIT);
    growth = {};
    const series = D.metrics.map((m) => {
      const mine = pts.filter((p) => p.metric === m.key);
      const g = growthRate(mine);
      if (g) growth[m.label] = g;
      return seriesFor(m.key, mine, showLabels);
    });
    const opt = baseOption();
    opt.series = series;
    chart.setOption(opt, { notMerge: false, replaceMerge: ["series"] });
    $("#visible-count").textContent = pts.length + " points shown";
    renderRefs(pts);
    renderTable(pts);
    syncMenus();
  }

  chart.on("legendselectchanged", (ev) => {
    const m = D.metrics.find((x) => x.label === ev.name);
    if (!m) return;
    if (ev.selected[ev.name]) state.metrics.add(m.key); else state.metrics.delete(m.key);
    render();
  });
  chart.on("click", (params) => { if (params.data && params.data.pt) showDetail(params.data.pt.product_id); });
  window.addEventListener("resize", () => chart.resize());

  // ------------------------------------------------------------------ detail panel
  function sourceLinks(refs) {
    return refs.map((n) => {
      const s = D.sources[n - 1];
      return '<a href="' + esc(s.url) + '" target="_blank" rel="noopener" title="' + esc(s.title) + '">[' + n + "]</a>";
    }).join(" ");
  }

  function showDetail(pid) {
    const prod = D.products[pid];
    if (!prod) return;
    state.selected = pid;
    const box = $("#detail");
    box.classList.remove("empty");
    const rows = D.metrics.filter((m) => prod.metrics[m.key]).map((m) => {
      const e = prod.metrics[m.key];
      const base = METRIC[m.key].baseline;
      return "<tr><td>" + esc(m.label) + (e.label && e.label !== prod.name ? " <span class=\"note\">(" + esc(e.label) + ")</span>" : "") + "</td>" +
        '<td class="num">' + fmtNum(e.value) + " " + esc(e.unit) + "</td>" +
        '<td class="num">' + fmtNorm(e.value / base) + "</td>" +
        "<td>" + sourceLinks(e.refs) + "</td>" +
        '<td class="note">' + esc(e.note || "") + "</td></tr>";
    }).join("");
    const allRefs = new Set();
    Object.values(prod.metrics).forEach((e) => e.refs.forEach((n) => allRefs.add(n)));
    box.innerHTML =
      "<h3>" + esc(prod.name) + ' <span class="badge ' + esc(prod.status) + '">' + esc(STATUS_LABEL[prod.status] || prod.status) + "</span></h3>" +
      '<div class="meta"><span>' + esc(prod.vendor) + "</span><span>" + fmtDate(prod.date, prod.date_precision) + "</span><span>" +
      esc(DATASET_LABEL[prod.dataset] || prod.dataset) + "</span>" + (prod.kind === "model" ? "<span>Model</span>" : "") + "</div>" +
      (prod.note ? '<p class="note">' + esc(prod.note) + "</p>" : "") +
      "<table><thead><tr><th>Metric</th><th>Value</th><th>Normalized</th><th>Sources</th><th>Note</th></tr></thead><tbody>" + rows + "</tbody></table>" +
      '<div class="links">' +
      (prod.corpus_url ? '<a class="btn small" href="' + esc(prod.corpus_url) + '" target="_blank" rel="noopener">Corpus notes: ' + esc(prod.corpus) + "</a>" : "") +
      "</div>";
    highlightRefs(allRefs);
    box.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }

  // ------------------------------------------------------------------ references
  function renderRefs(pts) {
    const used = new Set();
    pts.forEach((p) => p.refs.forEach((n) => used.add(n)));
    const ol = $("#refs");
    if (!ol.childElementCount) {
      ol.innerHTML = D.sources.map((s) =>
        '<li id="ref-' + s.n + '">' + esc(s.org ? s.org + ". " : "") + esc(s.title) + ". " +
        (s.venue ? esc(s.venue) + ", " : "") + esc(s.year) + ". " +
        '<a class="url" href="' + esc(s.url) + '" target="_blank" rel="noopener">' + esc(s.url) + "</a>" +
        (s.note ? ' <span class="src-note">' + esc(s.note) + "</span>" : "") + "</li>").join("");
    }
    D.sources.forEach((s) => { $("#ref-" + s.n).classList.toggle("dim", !used.has(s.n)); });
    $("#refs-count").textContent = "(" + D.sources.length + " sources, " + used.size + " used by the visible points)";
  }
  function highlightRefs(set) {
    D.sources.forEach((s) => { $("#ref-" + s.n).classList.toggle("hl", set.has(s.n)); });
  }

  // ------------------------------------------------------------------ table view
  function renderTable(pts) {
    const t = $("#data-table");
    const rows = pts.slice().sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0)).map((p) =>
      "<tr><td>" + esc(p.label) + (p.label !== p.name ? " (" + esc(p.name) + ")" : "") + "</td><td>" + esc(p.vendor) + "</td><td>" + fmtDate(p.date, p.date_precision) + "</td><td>" +
      esc(METRIC[p.metric].label) + '</td><td class="num">' + fmtNum(p.value) + " " + esc(p.unit) + '</td><td class="num">' + fmtNorm(p.normalized) +
      "</td><td>" + esc(STATUS_LABEL[p.status] || p.status) + "</td><td>" + esc(DATASET_LABEL[p.dataset] || p.dataset) + "</td><td>" + refTag(p.refs) + "</td></tr>").join("");
    t.innerHTML = "<thead><tr><th>Point</th><th>Vendor / org</th><th>Date</th><th>Metric</th><th>Value</th><th>Normalized</th><th>Status</th><th>Data set</th><th>Refs</th></tr></thead><tbody>" + rows + "</tbody>";
  }

  // ------------------------------------------------------------------ controls
  $("#labels-toggle").addEventListener("change", (ev) => { state.labels = ev.target.checked; render(); });
  $("#reset-btn").addEventListener("click", () => {
    Object.keys(ALL).forEach((g) => { state[g] = new Set(ALL[g]); });
    state.labels = "auto";
    chart.dispatchAction({ type: "restore" });
    render();
  });
  const paper = $("#paper-link");
  if (window.PAPER_URL) { paper.href = window.PAPER_URL; paper.hidden = false; }

  buildMenus();
  render();
})();
